const people = [
  {name: 'Alice', dept: 'eng', level: 'senior'},
  {name: 'Bob', dept: 'sales', level: 'junior'},
  {name: 'Charlie', dept: 'eng', level: 'junior'},
  {name: 'Diana', dept: 'sales', level: 'senior'}
];
const grouped = people.reduce((acc, p) => {
  const key = p.dept + '-' + p.level;
  acc[key] = acc[key] || [];
  acc[key].push(p.name);
  return acc;
}, {});
console.log(grouped);
